import math

def check_counterexample(m, N):
    """
    Checks if set N is a counterexample for modulus m.
    N must be a list/tuple of m distinct positive integers.
    """
    if len(N) != m:
        return False, "Incorrect size"

    # 1. Check Condition (1): Sum is not divisible by m
    sum_N = sum(N)
    if sum_N % m == 0:
        return False, f"Fails Condition (1): Sum is divisible by {m} ({sum_N})"

    # 2. Check Condition (2): For ALL permutations k, weighted sum is not divisible by m

    # Generate all permutations k of N
    all_permutations = list(itertools.permutations(N))

    for k in all_permutations:
        # Calculate weighted sum S = 1*k[0] + 2*k[1] + ... + m*k[m-1]
        weighted_sum = 0
        for i in range(m):
            # i+1 is the weight, k[i] is the element from N
            weighted_sum += (i + 1) * k[i]

        if weighted_sum % m == 0:
            # Found a permutation where the sum IS divisible by m.
            # Therefore, N is NOT a counterexample.
            return False, f"Fails Condition (2): Found permutation {k} with weighted sum {weighted_sum} divisible by {m}"

    # If we reached here, Condition (1) passed, and Condition (2) passed (all permutations failed to be divisible by m).
    return True, f"SUCCESS: Counterexample found for m={m} with set N={N}"

