def is_square_free(n):
    """Checks if a positive integer n is square-free."""
    if n <= 0:
        return False
    i = 2
    while i * i <= n:
        if n % (i * i) == 0:
            return False
        i += 1
    return True

count = 0
for m in range(2, 2001):
    if is_square_free(m):
        count += 1

print(count)
